// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/reports/sales-summary", wrapper.GetSalesSummaryReport)
	router.GET(options.BaseURL+"/reports/product-performance", wrapper.GetProductPerformanceReport)
	router.GET(options.BaseURL+"/reports/product-performance-matrix", wrapper.GetProductPerformanceMatrix)
	router.GET(options.BaseURL+"/reports/customer-performance", wrapper.GetCustomerPerformanceReport)
	router.GET(options.BaseURL+"/reports/category-performance", wrapper.GetCategoryPerformanceReport)
	router.GET(options.BaseURL+"/reports/slow-moving-products", wrapper.GetSlowMovingProductsReport)
	router.GET(options.BaseURL+"/reports/profitability", wrapper.GetProfitabilityReport)
	router.GET(options.BaseURL+"/reports/inventory-sales", wrapper.GetInventorySalesReport)
	router.GET(options.BaseURL+"/reports/customer-rfm", wrapper.GetCustomerRFMReport)
	router.GET(options.BaseURL+"/reports/promotions/:promotionId/performance", wrapper.GetPromotionPerformanceReport)
	router.GET(options.BaseURL+"/reports/customer-cohorts", wrapper.GetCustomerCohortsReport)
	router.GET(options.BaseURL+"/reports/product-lifecycle", wrapper.GetProductLifecycleReport)
	router.GET(options.BaseURL+"/reports/profitability-trend", wrapper.GetProfitabilityTrendReport)
	router.GET(options.BaseURL+"/reports/revenue-by-channel", wrapper.GetRevenueByChannelReport)
	router.GET(options.BaseURL+"/reports/sales-trends", wrapper.GetSalesTrendsReport)
	router.GET(options.BaseURL+"/reports/business-insights", wrapper.GetBusinessInsights)
	router.GET(options.BaseURL+"/reports/frequently-bought-together", wrapper.GetFrequentlyBoughtTogetherReport)
	router.GET(options.BaseURL+"/reports/stockout-risk", wrapper.GetStockoutRiskReport)
	router.GET(options.BaseURL+"/reports/product-recommendations", wrapper.GetProductRecommendations)
}

